// Each account uses the same workspace. Access control remains on the server.
import { bindPasswordVisibility } from './password-visibility.js?v=20261008-p1';
const app = document.querySelector('#app');
const $ = (selector, root = document) => root.querySelector(selector);
const $$ = (selector, root = document) => [...root.querySelectorAll(selector)];
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labels = {choice:'单选题',multiple:'多选题',boolean:'判断题',fill:'填空题',short:'简答题'};
const trackLabels = {general:'自定义题库',english:'英语',postgraduate:'考研英语',ielts:'雅思'};
const moduleLabels = {general:'综合',vocabulary:'词汇',reading:'阅读',listening:'听力',writing:'写作',speaking:'口语',cloze:'完形填空',translation:'翻译','new-type':'新题型'};
const modules = {general:['general'],english:['vocabulary','reading','listening','writing','speaking','translation'],postgraduate:['vocabulary','cloze','reading','new-type','translation','writing'],ielts:['vocabulary','listening','reading','writing','speaking']};
const token = () => sessionStorage.getItem('quizforge-session-token') || '';
const accountName = () => sessionStorage.getItem('quizforge-candidate-name') || '';
const json = body => ({headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});
const date = value => value ? new Date(value).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}) : '';
const countQuestions = bank => bank.questionCount ?? Object.values(bank.typeCounts || {}).reduce((sum,n)=>sum+Number(n),0);
let cleanup = () => {};
let toastTimer;
function toast(message,error=false){const node=$('#toast');node.textContent=message;node.className=`toast${error?' error':''}`;clearTimeout(toastTimer);toastTimer=setTimeout(()=>node.classList.add('hidden'),4500);}
async function api(url, options={}) {
  const headers = new Headers(options.headers || {});if(token())headers.set('x-session-token',token());
  const response=await fetch(url,{...options,headers}),data=await response.json().catch(()=>({}));
  if(!response.ok){if(response.status===401&&!url.endsWith('/login')){sessionStorage.removeItem('quizforge-session-token');go('/login');}throw new Error(data.error||'操作失败，请重试');}return data;
}
function go(path){const target=path.replace(/^#/, '')||'/';history.pushState(null,'',target);route();}
function heading(title,description='',actions=''){return `<section class="page-heading"><div><h1>${esc(title)}</h1>${description?`<p>${esc(description)}</p>`:''}</div>${actions?`<div class="actions">${actions}</div>`:''}</section>`;}
function empty(title,description='',link='',action=''){return `<div class="empty-state"><div class="empty-icon" aria-hidden="true">▤</div><h3>${esc(title)}</h3>${description?`<p>${esc(description)}</p>`:''}${link?`<a class="button secondary" href="${esc(link)}">${esc(action)}</a>`:''}</div>`;}
function stat(title,value,note=''){return `<div class="stat"><div class="stat-label">${esc(title)}</div><div class="stat-value">${esc(value)}</div><div class="stat-note">${esc(note)}</div></div>`;}
function status(form,message,error=false){const node=$('[data-status]',form);if(node){node.textContent=message;node.className=error?'form-error':'success';}}
function bindForm(form,action){form.onsubmit=async event=>{event.preventDefault();const buttons=$$('button[type="submit"]',form);buttons.forEach(button=>button.disabled=true);status(form,'');try{await action(new FormData(form),form);}catch(error){status(form,error.message,true);}finally{buttons.forEach(button=>{if(button.isConnected)button.disabled=false;});}};}
function dialog(title,content){$$('dialog').forEach(x=>x.remove());const node=document.createElement('dialog');node.className='dialog';node.innerHTML=`<div class="dialog-header"><h2>${esc(title)}</h2><button type="button" class="icon-button" aria-label="关闭">×</button></div><div class="dialog-body">${content}</div>`;document.body.append(node);$('.dialog-header button',node).onclick=()=>node.close();node.addEventListener('close',()=>node.remove());node.showModal();return node;}
function trackOptions(selected='general'){return Object.entries(trackLabels).map(([value,label])=>`<option value="${value}" ${value===selected?'selected':''}>${label}</option>`).join('');}
function moduleOptions(track,selected='general'){return (modules[track]||modules.general).map(value=>`<option value="${value}" ${value===selected?'selected':''}>${moduleLabels[value]}</option>`).join('');}
function metaFields(bank={}){return `<div class="form-grid"><label>所属方向<select name="track">${trackOptions(bank.track)}</select></label><label>自定义分类<input name="category" value="${esc(bank.category||bank.course||'')}" maxlength="80" placeholder="例如：软考、酿酒工、计算机"></label><label>学习模块<select name="module">${moduleOptions(bank.track||'general',bank.module)}</select></label><label>难度<select name="difficulty">${[['mixed','综合'],['easy','基础'],['medium','中等'],['hard','困难']].map(([v,t])=>`<option value="${v}" ${bank.difficulty===v?'selected':''}>${t}</option>`).join('')}</select></label></div>`;}
function bindMeta(form){const track=$('[name="track"]',form),module=$('[name="module"]',form);const update=()=>module.closest('label').classList.toggle('hidden',(modules[track.value]||modules.general).length===1);track.onchange=()=>{module.innerHTML=moduleOptions(track.value);update();};update();}
function setNavigation(section){const logged=Boolean(token());$('#siteHeader').classList.toggle('hidden',!logged);$('#workspace').classList.toggle('signed-out',!logged);$('#accountName').textContent=accountName();$$('#mainNav a').forEach(a=>{const active=a.dataset.section===section;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});}
$('#navToggle').onclick=()=>{const open=$('#mainNav').classList.toggle('open');$('#navToggle').setAttribute('aria-expanded',String(open));};
$$('#mainNav a').forEach(a=>a.addEventListener('click',()=>{$('#mainNav').classList.remove('open');$('#navToggle').setAttribute('aria-expanded','false');}));
$('#logoutButton').onclick=async()=>{await api('/api/session/logout',{method:'POST'}).catch(()=>{});['quizforge-session-token','quizforge-candidate-name','quizforge-role','quizforge-candidate-password'].forEach(key=>sessionStorage.removeItem(key));go('#/login');};

async function login(){setNavigation('');app.innerHTML=`<section class="login-shell"><div><div class="login-card"><a class="brand" href="/login"><span class="brand-icon">智</span><span>智题工坊<small>我的学习空间</small></span></a><h1>欢迎回来</h1><p>管理自己的题库，开始考研英语与雅思学习。</p><form id="loginForm"><label for="username">账号</label><input id="username" name="username" autocomplete="username" maxlength="60" required><label for="password">密码</label><div class="login-password-field"><input id="password" name="password" type="password" autocomplete="current-password" required><button id="passwordToggle" type="button" class="password-toggle" aria-controls="password" aria-label="显示密码" aria-pressed="false">显示</button></div><button type="submit">进入学习空间 →</button><p data-status aria-live="polite"></p></form></div><div class="login-footer">自定义题库 · 英语 · 雅思</div></div></section>`;bindPasswordVisibility($('#password'),$('#passwordToggle'));bindForm($('#loginForm'),async fd=>{const result=await api('/api/account/login',{method:'POST',...json(Object.fromEntries(fd))});sessionStorage.setItem('quizforge-session-token',result.token);sessionStorage.setItem('quizforge-candidate-name',result.name);sessionStorage.removeItem('quizforge-role');go('#/');});}

function bankRow(bank){return `<div class="bank-row"><span class="bank-symbol" aria-hidden="true">▤</span><div class="bank-info"><h3>${esc(bank.title)}</h3><div class="meta">${esc(bank.category||trackLabels[bank.track]||'未分类')} · ${countQuestions(bank)} 道题</div></div><div class="actions"><a class="button small secondary" href="/bank/${bank.id}">查看题目</a><a class="button small" href="/build/${bank.id}">开始练习</a></div></div>`;}
function bankCard(bank){return `<article class="card bank-card"><div class="bank-tags"><span class="badge">${esc(bank.category||'未分类')}</span></div><h3>${esc(bank.title)}</h3><p class="meta">${countQuestions(bank)} 道题 · ${Object.entries(bank.typeCounts||{}).filter(([,n])=>n).map(([t,n])=>`${labels[t]||t} ${n}`).join(' / ')||'等待添加题目'}</p><div class="actions"><a class="button" href="/build/${bank.id}">开始练习</a><a class="button secondary" href="/bank/${bank.id}">查看题目</a></div></article>`;}
async function home(){
  const [banks,today,attempts,exams]=await Promise.all([api('/api/banks'),api('/api/study/today'),api('/api/attempts'),api('/api/exams')]);
  const pending=exams.filter(x=>!x.completedAt&&x.status!=='completed');
  const recentIds=[...new Set([...exams].sort((a,b)=>String(b.createdAt).localeCompare(String(a.createdAt))).map(e=>e.bankId).filter(Boolean))];
  const recent=[...recentIds.map(id=>banks.find(b=>b.id===id)).filter(Boolean),...banks.filter(b=>!recentIds.includes(b.id))].slice(0,5);
  app.innerHTML=heading('今天的学习','', '<a class="button secondary" href="/banks">全部题库</a>')+`
  ${pending.length?`<section class="card continue-card"><div class="card-heading"><h2>继续上次练习</h2><span class="badge">${pending.length} 份未完成</span></div>${pending.slice(0,3).map(e=>`<div class="bank-row"><div class="bank-info"><h3>${esc(e.title)}</h3><p class="meta">${date(e.createdAt)}</p></div><a class="button" href="/exam/${e.id}">继续作答</a></div>`).join('')}</section>`:''}
  <section class="today-actions"><a class="card" href="/english"><h2>考研英语</h2><p>考研词汇 · 选择与拼写练习</p><b>选择范围，开始学习 →</b></a><a class="card" href="/banks/wrong"><h2>题库错题复习</h2><p>按题库筛选，巩固薄弱知识点</p><b>查看错题 →</b></a><a class="card" href="/ielts"><h2>雅思专项练习</h2><p>阅读题库 · 写作与口语笔记</p><b>进入专项 →</b></a></section>
  <section class="card"><div class="card-heading"><h2>${recentIds.length?'最近使用的题库':'选择一套题库开始'}</h2><span class="meta">全部方向 · ${banks.length} 个题库</span></div>${recent.length?recent.map(bankRow).join(''):empty('还没有题库','上传带答案的资料，检查后即可练习。','#/import','导入题库')}</section>
  <div class="summary-line"><span>已完成 ${attempts.length} 次练习</span><span>待复习 ${today.dueWords||0} 个单词</span><span class="actions"><a href="/banks/results">题库记录</a><a href="/english/results">考研记录</a><a href="/ielts/results">雅思记录</a></span></div>`;
}

async function banks(){const rows=await api('/api/banks');app.innerHTML=heading('我的题库','科目不限。把资料整理成题库，再按需要随机练习。','<button class="secondary" id="createBank">手动建题库</button><a class="button" href="/import">导入题库</a>')+`<div class="filter-bar"><label class="grow search-field"><span class="hidden">搜索题库</span><input id="bankSearch" placeholder="搜索题库名称、分类"></label><label><span class="hidden">分类</span><select id="bankCategory"><option value="">全部分类</option>${[...new Set(rows.map(x=>x.category||x.course).filter(Boolean))].map(c=>`<option value="${esc(c)}">${esc(c)}</option>`).join('')}</select></label><label><span class="hidden">所属方向</span><select id="bankTrack"><option value="">全部方向</option>${trackOptions("")}</select></label></div><p class="meta" id="bankCount" style="margin-bottom:14px"></p><section id="bankList" class="grid"></section>`;const render=()=>{const search=$('#bankSearch').value.toLowerCase(),category=$('#bankCategory').value,track=$('#bankTrack').value,filtered=rows.filter(x=>(!search||`${x.title} ${x.category||x.course||''}`.toLowerCase().includes(search))&&(!category||(x.category||x.course)===category)&&(!track||x.track===track));$('#bankCount').textContent=`共 ${filtered.length} 个题库`;$('#bankList').innerHTML=filtered.length?filtered.map(bankCard).join(''):empty(rows.length?'没有匹配的题库':'建立第一套题库',rows.length?'当前筛选没有结果，题库并未被删除。':'可上传 PDF、Word、Markdown 或文本资料。')+(rows.length?'<button class="secondary" id="clearBankFilters">清除筛选</button>':'');const clear=$('#clearBankFilters');if(clear)clear.onclick=()=>{$('#bankSearch').value='';$('#bankCategory').value='';$('#bankTrack').value='';render();};};$('#bankSearch').oninput=render;$('#bankCategory').onchange=render;$('#bankTrack').onchange=render;$('#createBank').onclick=()=>editBankDialog();render();}
function editBankDialog(bank){const node=dialog(bank?'编辑题库信息':'手动创建题库',`<form class="form-stack" id="bankForm"><label>题库名称<input name="title" required maxlength="200" value="${esc(bank?.title||'')}" placeholder="例如：系统集成项目管理师模拟题"></label>${metaFields(bank)}<p data-status aria-live="polite"></p><div class="form-actions"><button type="submit">${bank?'保存信息':'创建并添加题目'}</button></div></form>`);const form=$('#bankForm',node);bindMeta(form);bindForm(form,async fd=>{const row=await api(bank?`/api/banks/${bank.id}`:'/api/banks',{method:bank?'PATCH':'POST',...json(Object.fromEntries(fd))});node.close();toast(bank?'题库信息已保存':'题库已创建');go(`#/bank/${bank?.id||row.id}`);});}

async function bankDetail(id){const data=await api(`/api/banks/${id}/questions`);const bank=data.bank||data,questions=data.questions||[];app.innerHTML=heading(bank.title||'题库详情',`${bank.category||bank.course||'未分类'} · ${questions.length} 道题`,'<button class="secondary" id="editBank">编辑信息</button><button id="addQuestion">添加题目</button>')+`<div class="card"><div class="card-heading"><div><h2>题目列表</h2><p class="meta">题干、选项、答案和解析均可修改。</p></div><a class="button" href="/build/${id}">随机组卷 →</a></div><div class="filter-bar"><label class="grow search-field"><span class="hidden">搜索题目</span><input id="questionSearch" placeholder="搜索题干"></label><label><span class="hidden">题型</span><select id="questionType"><option value="">全部题型</option>${Object.entries(labels).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></label></div><div id="questionList"></div><div class="form-actions"><a class="button secondary" href="/banks">返回题库</a><button class="secondary" id="exportBank">导出题库</button><button class="secondary" id="exportBankAnswers">导出题库及答案</button><button class="danger" id="deleteBank">删除题库</button></div></div>`;$('#editBank').onclick=()=>editBankDialog({...bank,id});$('#addQuestion').onclick=()=>questionDialog(null,async q=>{await api(`/api/banks/${id}/questions`,{method:'POST',...json(q)});bankDetail(id);});$('#deleteBank').onclick=async()=>{if(!confirm(`删除「${bank.title}」题库及其中的题目？已完成的答题记录会保留。`))return;try{await api(`/api/banks/${id}`,{method:'DELETE'});toast('题库已删除');go('#/banks');}catch(e){toast(e.message,true);}};const render=()=>{const q=$('#questionSearch').value.toLowerCase(),type=$('#questionType').value;const selected=questions.map((question,index)=>({question,index})).filter(x=>(!q||x.question.question.toLowerCase().includes(q))&&(!type||x.question.type===type));$('#questionList').innerHTML=selected.length?selected.map(({question,index})=>`<article class="review-item"><div class="question-head"><span class="badge">${labels[question.type]}</span><span class="meta">第 ${index+1} 题</span></div><p class="question-title">${esc(question.question)}</p>${answerReview(question,question.answer)}<div class="review-actions"><button class="small secondary" data-edit="${index}">编辑题目</button><button class="small ghost" data-delete="${index}">删除</button></div></article>`).join(''):empty('暂无题目','添加题目后，就可以随机组卷练习。');$$('[data-edit]').forEach(button=>button.onclick=()=>questionDialog(questions[Number(button.dataset.edit)],async question=>{await api(`/api/banks/${id}/questions/${button.dataset.edit}`,{method:'PUT',...json(question)});bankDetail(id);}));$$('[data-delete]').forEach(button=>button.onclick=async()=>{if(!confirm(`删除第 ${Number(button.dataset.delete)+1} 题？`))return;try{await api(`/api/banks/${id}/questions/${button.dataset.delete}`,{method:'DELETE'});bankDetail(id);}catch(e){toast(e.message,true);}});};$('#questionSearch').oninput=render;$('#questionType').onchange=render;render();}

function answerText(q){if(q.type==='boolean')return q.answer===true?'true':q.answer===false?'false':'';if(q.type==='choice'||q.type==='multiple'){if(typeof q.answer==='string'&&/[A-H]/i.test(q.answer))return q.answer;return (Array.isArray(q.answer)?q.answer:[q.answer]).filter(x=>Number.isInteger(x)).map(x=>String.fromCharCode(65+x)).join('');}if(q.type==='fill')return (q.blanks?.map(x=>x.answers)||q.answer||[]).map(a=>(Array.isArray(a)?a:[a]).join('/')).join('；');return (Array.isArray(q.answer)?q.answer:[q.answer]).filter(Boolean).join('\n');}
function questionDialog(original,onSave){const q=original?structuredClone(original):{type:'choice',question:'',options:['','','',''],answer:null,explanation:''};const node=dialog(original?'编辑题目':'新增题目',`<form id="questionForm" class="form-stack"><label>题型<select name="type">${Object.entries(labels).map(([k,v])=>`<option value="${k}" ${q.type===k?'selected':''}>${v}</option>`).join('')}</select></label><label>题干<textarea name="question" rows="3" required>${esc(q.question)}</textarea></label><div id="questionAnswerFields"></div><label>解析（可选）<textarea name="explanation" rows="2">${esc(q.explanation||'')}</textarea></label><details><summary>阅读或听力材料（可选）</summary><div class="form-stack"><div class="form-grid"><label>题组编号<input name="groupId" value="${esc(q.groupId||'')}" placeholder="相同材料填写相同编号"></label><label>材料标题<input name="materialTitle" value="${esc(q.materialTitle||'')}"></label></div><label>材料正文<textarea name="materialText" rows="5">${esc(q.materialText||'')}</textarea></label></div></details><p data-status aria-live="polite"></p><div class="form-actions"><button type="submit">保存题目</button></div></form>`);const form=$('#questionForm',node);const render=()=>{const type=$('[name="type"]',form).value,same=type===q.type,answer=same?answerText(q):'';$('#questionAnswerFields',node).innerHTML=(['choice','multiple'].includes(type)?`<label>选项</label><div id="optionFields">${(same&&q.options?.length?q.options:['','','','']).map((v,i)=>`<div class="option-edit"><span>${String.fromCharCode(65+i)}</span><input name="option" aria-label="选项 ${String.fromCharCode(65+i)}" value="${esc(v)}"></div>`).join('')}</div><button type="button" class="small secondary" id="addOption">添加选项</button><label style="margin-top:18px">正确答案<input name="answer" value="${esc(answer)}" placeholder="${type==='choice'?'填写字母，如 A':'填写多个字母，如 AC'}" required></label>`:type==='boolean'?`<label>正确答案<select name="answer" required><option value="">请选择</option><option value="true" ${answer==='true'?'selected':''}>正确</option><option value="false" ${answer==='false'?'selected':''}>错误</option></select></label>`:`<label>${type==='fill'?'各空的标准答案':'可接受的标准答案'}<textarea name="answer" rows="3" required>${esc(answer)}</textarea></label><p class="form-note">${type==='fill'?'每空用分号分隔；同一空的等价答案用 / 分隔。例如：酵母/酵母菌；30':'多个等价答案分别另起一行。简答按标准答案匹配；作文和口语长答建议使用雅思专项练习记录。'}</p>`);const add=$('#addOption',node);if(add)add.onclick=()=>{const options=$$('#optionFields input',node);if(options.length>=8)return toast('最多支持 8 个选项');$('#optionFields',node).insertAdjacentHTML('beforeend',`<div class="option-edit"><span>${String.fromCharCode(65+options.length)}</span><input name="option" aria-label="选项 ${String.fromCharCode(65+options.length)}"></div>`);};};$('[name="type"]',form).onchange=render;render();bindForm(form,async fd=>{const type=fd.get('type'),raw=String(fd.get('answer')||'').trim();let answer,options=[];if(['choice','multiple'].includes(type)){options=fd.getAll('option').map(x=>String(x).trim());while(options.at(-1)==='')options.pop();if(options.length<2||options.some(x=>!x))throw new Error('至少填写两个选项，中间不能留空。');const letters=raw.toUpperCase().replace(/[\s,，、]/g,'');if(!/^[A-H]+$/.test(letters))throw new Error('答案请填写选项字母，例如 A 或 AC。');const indices=[...new Set([...letters].map(c=>c.charCodeAt(0)-65))];if(indices.some(x=>x>=options.length))throw new Error('答案字母超出了已有选项。');if(type==='choice'&&indices.length!==1)throw new Error('单选题只能有一个正确答案。');answer=type==='choice'?indices[0]:indices;}else if(type==='boolean')answer=raw==='true';else if(type==='fill')answer=raw.split(/[;；]/).map(x=>x.split('/').map(v=>v.trim()).filter(Boolean)).filter(x=>x.length);else answer=raw.split('\n').map(x=>x.trim()).filter(Boolean);const result={...q,type,question:String(fd.get('question')).trim(),options,answer,blanks:type==='fill'?answer.map(answers=>({answers})):[],explanation:String(fd.get('explanation')||''),groupId:String(fd.get('groupId')||''),materialTitle:String(fd.get('materialTitle')||''),materialText:String(fd.get('materialText')||''),points:['multiple','fill','short'].includes(type)?2:1};await onSave(result);node.close();toast('题目已保存');});}

