function bindHistory(scope,type){const change=()=>{const params=new URLSearchParams();const track=$('#historyTrack')?.value||scope;if(track==='english')params.set('track','english');if($('#historyBank').value)params.set('bankId',$('#historyBank').value);if($('#historyModule').value)params.set('module',$('#historyModule').value);go('/'+scopeRoot(scope)+'/'+type+(params.size?'?'+params:''));};$('#historyTrack')?.addEventListener('change',()=>go('/english/'+type+($('#historyTrack').value==='english'?'?track=english':'')));$('#historyBank').onchange=change;$('#historyModule').onchange=change;}

async function results(scope='general'){const filters=historyFilters(scope),[attempts,allExams,banks]=await Promise.all([api('/api/attempts?'+new URLSearchParams(filters)),api('/api/exams'),api('/api/banks')]),exams=allExams.filter(e=>(e.track||'general')===scope&&(!filters.bankId||e.bankId===filters.bankId)&&(!filters.module||e.module===filters.module)),pending=exams.filter(e=>!e.completedAt&&e.status!=='completed'),average=attempts.length?Math.round(attempts.reduce((s,a)=>s+Number(a.percentage??(a.maxScore?a.score/a.maxScore*100:0)),0)/attempts.length):0;app.innerHTML=heading(scopeName(scope)+' · 学习记录','查看已完成的练习，也可以继续尚未提交的试卷。',`<a class="button secondary" href="/${scopeRoot(scope)}/wrong${scope==='english'?'?track=english':''}">查看错题本 →</a>`)+historyControls(scope,banks)+`<section class="stats-grid">${stat('已完成练习',attempts.length)}${stat('平均得分率',`${average}%`)}${stat('未完成练习',pending.length)}${stat('累计练习题目',attempts.reduce((s,a)=>s+Number(a.questionCount||0),0))}</section>${pending.length?`<section class="card"><div class="card-heading"><h2>继续练习</h2></div>${pending.map(e=>`<div class="bank-row"><div class="bank-info"><h3>${esc(e.title)}</h3><p class="meta">${date(e.createdAt)}</p></div><div class="actions"><a class="button small" href="/exam/${e.id}">继续作答</a><button class="small secondary" data-delete-exam="${e.id}">删除</button></div></div>`).join('')}</section>`:''}<section class="card"><div class="card-heading"><h2>已完成的练习</h2></div>${attempts.length?`<div class="table-wrap"><table><thead><tr><th>试卷</th><th>得分</th><th>错题</th><th>完成时间</th><th></th></tr></thead><tbody>${attempts.map(a=>`<tr><td>${esc(a.title)}</td><td><b>${Number(a.score).toFixed(1)}</b><span class="meta"> / ${Number(a.maxScore).toFixed(1)}</span></td><td>${a.wrongCount??(a.results||[]).filter(r=>r.score<r.maxPoints).length} 题</td><td class="meta">${date(a.createdAt)}</td><td><a class="button small secondary" href="/attempt/${a.id}">查看结果</a></td></tr>`).join('')}</tbody></table></div>`:empty('还没有完成练习','完成本模块的练习后，就会显示在这里。','/'+scopeRoot(scope),'开始学习')}</section>`;if(scope==='ielts'&&!filters.bankId){const journal=(await api('/api/study/journal')).filter(r=>r.track==='ielts'&&(!filters.module||r.module===filters.module));app.insertAdjacentHTML('beforeend',`<section class="card"><div class="card-heading"><h2>写作与口语复盘</h2><span class="badge">${journal.length} 条</span></div>${journal.length?journal.map(r=>`<details class="journal-item"><summary>${esc(moduleLabels[r.module])} · ${esc(r.prompt)}</summary><p class="meta">${date(r.createdAt)}</p><p class="journal-response">${esc(r.response)}</p>${r.notes?`<p class="journal-response">复盘：${esc(r.notes)}</p>`:''}<a href="/ielts/${r.module}">进入${esc(moduleLabels[r.module])}练习 →</a></details>`).join(''):'<p class="meta">保存写作或口语练习后，会显示在这里。</p>'}</section>`);}$$('[data-delete-exam]').forEach(button=>button.onclick=async()=>{if(!confirm('删除这份未完成试卷？'))return;try{await api(`/api/exams/${button.dataset.deleteExam}`,{method:'DELETE'});results(scope);}catch(error){toast(error.message,true);}});bindHistory(scope,'results');}
async function attempt(id){const row=await api(`/api/attempts/${id}`);setNavigation(scopeRoot(row.track));const wrong=(row.results||[]).filter(r=>r.score<r.maxPoints).length;app.innerHTML=heading(row.title,'练习结果 · '+date(row.createdAt),`<a class="button secondary" href="/${scopeRoot(row.track)}/results${row.track==='english'?'?track=english':''}">返回学习记录</a>`)+`<section class="card"><div class="card-heading"><div><div class="result-score">${Number(row.score).toFixed(1)} <small>/ ${Number(row.maxScore).toFixed(1)} 分</small></div><p class="meta">${row.results.length} 道题 · ${wrong} 道错题</p></div><span class="badge green">已完成</span></div><div class="actions"><button id="retryWrong" ${wrong?'':'disabled'}>重练本次错题</button><a class="button secondary" href="${row.quizId?'#/build/'+row.quizId:'#/banks'}">${row.quizId?'再来一组':'选择题库'}</a><button class="secondary small" id="toggleWrong" ${wrong?'':'disabled'}>只看错题</button><details class="export-menu"><summary>导出</summary><div class="actions"><button class="secondary small" id="exportReport">答题报告</button><button class="secondary small" id="exportWrong" ${wrong?'':'disabled'}>本次错题</button></div></details></div></section><div id="reviewResults">${row.results.map((r,i)=>{const q=row.questions[r.index??i],bad=r.score<r.maxPoints;return `<article class="question" data-wrong="${bad}"><div class="question-title">${i+1}. ${esc(q.question)}</div><p class="review-status ${bad?'wrong':'right'}">${Number(r.score).toFixed(1)} / ${Number(r.maxPoints).toFixed(1)} 分 · ${esc(r.feedback)}</p>${answerReview(q,r.correctAnswer,row.answers[r.index??i],true)}${r.explanation?`<div class="explanation">解析：${esc(r.explanation)}</div>`:''}</article>`;}).join('')}</div>`;$('#retryWrong').onclick=async event=>{const button=event.currentTarget;button.disabled=true;try{const paper=await api('/api/attempts/'+id+'/retry',{method:'POST',...json({})});go('#/exam/'+paper.id);}catch(e){toast(e.message,true);button.disabled=false;}};$('#exportReport').onclick=()=>download(`/api/attempts/${id}/export`,`${row.title}-答题报告.docx`);$('#exportWrong').onclick=()=>download(`/api/attempts/${id}/export?wrongOnly=1`,`${row.title}-错题.docx`);$('#toggleWrong').onclick=event=>{const only=event.target.dataset.only!=='true';event.target.dataset.only=String(only);event.target.textContent=only?'显示全部题目':'只看错题';$$('[data-wrong]').forEach(item=>item.classList.toggle('hidden',only&&item.dataset.wrong!=='true'));};return row.track;}
async function wrong(scope='general'){const filters=historyFilters(scope),query=new URLSearchParams(filters),[rows,banks]=await Promise.all([api('/api/wrong-questions?'+query),api('/api/banks')]);app.innerHTML=heading(scopeName(scope)+' · 错题本','按出错次数整理，反复练习容易混淆的知识点。',rows.length?'<button class="secondary" id="exportWrongBook">导出错题本</button><button id="practiceWrong">随机练习错题</button>':'')+historyControls(scope,banks)+`<section>${rows.length?rows.map((q,i)=>`<article class="question"><div class="question-head"><span class="badge">${labels[q.type]}</span><span class="badge orange">错 ${q.wrongCount} 次</span></div><p class="question-title">${i+1}. ${esc(q.question)}</p>${answerReview(q,q.correctAnswer)}${q.explanation?`<div class="explanation">解析：${esc(q.explanation)}</div>`:''}</article>`).join(''):`<div class="card">${empty('暂时没有错题','完成本模块的练习后，答错的题目会自动保存在这里。','/'+scopeRoot(scope),'开始练习')}</div>`}</section>`;if(rows.length){$('#exportWrongBook').onclick=()=>download('/api/wrong-questions/export?'+query,scopeName(scope)+'错题本.docx');$('#practiceWrong').onclick=async()=>{try{const paper=await api('/api/wrong-exam',{method:'POST',...json(filters)});go(`#/exam/${paper.id}`);}catch(e){toast(e.message,true);}};}bindHistory(scope,'wrong');}

function englishTabs(){return '';}
async function english(page='overview'){const name=page==='dictionary'?'本地词典':page==='collections'?'我的词库':page==='translate'?'中英翻译':page==='import'?'导入英语词汇':'考研英语';app.innerHTML=heading(name,page==='overview'?'先积累单词，再用拼写和选择练习巩固记忆。':'')+englishTabs(page)+'<div id="englishContent"></div>';if(page==='dictionary')return dictionary();if(page==='collections')return collections();if(page==='translate')return translation();if(page==='import')return vocabularyImport();const [today,banks,overview]=await Promise.all([api('/api/study/today?track=postgraduate'),api('/api/banks'),api('/api/study/postgraduate')]);const list=banks.filter(b=>b.track==='postgraduate');$('#englishContent').innerHTML=`<section class="stats-grid compact-stats">${stat('考研词汇',overview.wordCount||0,'当前可用考研词汇')}${stat('已掌握',overview.progress?.mastered||0,'练习中积累掌握记录')}${stat('待复习',today.dueWords||0,'复习后更新学习进度')}${stat('英语题库',list.length,'包含自建与导入资料')}</section><div class="split-layout"><section class="card"><div class="card-heading"><div><h2>单词随机练习</h2><p class="meta">选择词汇范围即可开始，也可以调整练习设置。</p></div></div>${practiceFormHtml('wordPractice','postgraduate')}<p class="form-note">默认练习考研词汇，可按需要切换范围。</p></section><section class="card"><h2>我的单词积累</h2><p class="meta" style="margin:12px 0 20px">查到的单词可以加入个人词库，后续只练习自己收藏的内容。</p><div class="actions"><a class="button secondary" href="/english/dictionary">去查词</a><a class="button secondary" href="/english/collections">我的词库</a></div></section></div><div class="section-head"><h2>考研专项题库</h2><a class="button small secondary" href="/import/postgraduate">导入考研题库</a></div><section class="grid">${list.length?list.map(bankCard).join(''):`<div class="card">${empty('还没有考研专项题库','上传阅读、完形或其他英语练习资料即可开始。')}</div>`}</section>`;bindPractice($('#wordPractice'));}
function practiceFormHtml(id,track='english',collection=false){return `<form id="${id}" class="form-stack"><div class="form-grid">${collection?'':`<label>词汇范围<select name="track"><option value="english" ${track==='english'?'selected':''}>英语基础</option><option value="postgraduate" ${track==='postgraduate'?'selected':''}>考研英语</option><option value="ielts" ${track==='ielts'?'selected':''}>雅思词汇</option></select></label>`}</div><details><summary>调整练习 · 方向、题型与数量</summary><div class="form-grid"><label>出题方向<select name="direction"><option value="en-zh">英语 → 中文</option><option value="zh-en">中文 → 英语</option></select></label><label>练习方式<select name="mode"><option value="choice">选择正确释义</option><option value="spell">拼写填空</option></select></label><label>题目数量<input name="count" type="number" min="1" max="200" value="10" required></label></div></details><p class="form-note" data-availability aria-live="polite">正在读取可用词汇…</p><div class="actions"><button type="button" class="small secondary" data-count="20">20 题</button><button type="button" class="small secondary" data-count="50">50 题</button><button type="button" class="small secondary" data-count="all">本轮全部</button></div><p data-status aria-live="polite"></p><div class="form-actions"><button type="submit">开始练习</button></div></form>`;}
function bindPractice(form,collectionId){let available=0;const refresh=async()=>{try{const options=await api('/api/vocabulary/practice-options?'+new URLSearchParams(collectionId?{collectionId}:{track:form.elements.track.value}));available=options.maxPerExam;form.elements.count.max=String(available||1);form.elements.count.value=String(Math.min(Number(form.elements.count.value)||10,available)||1);form.querySelector('[data-availability]').textContent='当前可用 '+options.available+' 个词，本轮可抽 1–'+available+' 题（最多 200 题），题库越大可抽越多。';form.querySelector('[type="submit"]').disabled=!available;}catch(e){status(form,e.message,true);}};form.elements.track?.addEventListener('change',refresh);form.querySelectorAll('[data-count]').forEach(button=>button.onclick=()=>{form.elements.count.value=String(Math.min(available,button.dataset.count==='all'?available:Number(button.dataset.count))||1);});refresh();bindForm(form,async fd=>{const row=await api(collectionId?'/api/collections/'+collectionId+'/practice':'/api/vocabulary/practice',{method:'POST',...json(Object.fromEntries(fd))});$$('dialog').forEach(d=>d.close());go('/exam/'+row.id);});}
async function dictionary(){const root=$('#englishContent');root.innerHTML=`<section class="card"><form id="lookupForm" class="lookup-form"><label>查询语种<select name="language"><option value="en">英语</option><option value="zh">中文</option><option value="auto">自动识别</option></select></label><label>单词或释义<input name="q" autocomplete="off" placeholder="输入单词，例如 improve" required></label><button type="submit">查询</button><p data-status aria-live="polite"></p></form></section><div class="section-head"><h2 id="wordHeading">词库中的单词</h2><label class="inline" style="margin:0"><span class="meta">范围</span><select id="wordTrack" style="width:145px;min-height:34px;padding:5px 10px"><option value="">全部词汇</option><option value="english">英语基础</option><option value="postgraduate" selected>考研英语</option><option value="ielts">雅思</option></select></label></div><div id="wordResults" class="word-grid"></div><div id="wordPagination" class="pagination"></div>`;let page=0,currentWords=[];const render=words=>{currentWords=words;const visible=words.slice(page*12,page*12+12);$('#wordResults').innerHTML=words.length?visible.map(wordCard).join(''):empty('没有查到对应单词','试试另一查询语种，或在“导入词汇”中补充本地词库。');bindWordActions(visible);$('#wordPagination').innerHTML=words.length>12?`<button class="secondary" id="previousWords" ${page===0?'disabled':''}>上一页</button><span role="status">第 ${page+1} / ${Math.ceil(words.length/12)} 页</span><button class="secondary" id="nextWords" ${(page+1)*12>=words.length?'disabled':''}>下一页</button>`:'';for(const [id,step] of [['previousWords',-1],['nextWords',1]]){const button=$('#'+id);if(button)button.onclick=()=>{page+=step;render(currentWords);$('#wordHeading').scrollIntoView({block:'start'});};}};let activeQuery='';const load=async()=>{const track=$('#wordTrack').value,q=activeQuery,language=$('[name="language"]',$('#lookupForm')).value;const words=await api(`/api/vocabulary?${q?`q=${encodeURIComponent(q)}&language=${language}`:'browse=1'}${track?`&track=${track}`:''}`);$('#wordHeading').textContent=q?`查询结果（${words.length}）`:`词库中的单词（${words.length}）`;page=0;render(words);};bindForm($('#lookupForm'),async fd=>{activeQuery=String(fd.get('q')).trim();await load();});$('#wordTrack').onchange=()=>load().catch(e=>toast(e.message,true));await load();}
function wordCard(w){return `<article class="word-card"><div class="word-head"><h2 lang="en">${esc(w.en)}</h2><button class="icon-button" data-speak="${esc(w.en)}" aria-label="朗读 ${esc(w.en)}" title="朗读">◖))</button></div><span class="meta">${esc(w.pronunciation||'')}</span><p class="word-meaning">${esc(w.zh)}</p>${w.partOfSpeech?`<span class="badge">${esc(w.partOfSpeech)}</span>`:''}${w.exampleEn?`<details class="word-example"><summary>查看例句</summary><span lang="en">${esc(w.exampleEn)}</span><small>${esc(w.exampleZh||'')}</small></details>`:''}<div class="word-actions"><span class="meta">${esc(trackLabels[w.track]||'英语')}</span><button class="small secondary" data-collect="${w.id}">＋ 收藏</button></div></article>`;}
function speak(text){if(!('speechSynthesis' in window))return toast('当前浏览器不支持朗读。');speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(text);utterance.lang=/[\u4e00-\u9fff]/.test(text)?'zh-CN':'en-US';speechSynthesis.speak(utterance);}
function bindWordActions(words){$$('[data-speak]').forEach(button=>button.onclick=()=>speak(button.dataset.speak));$$('[data-collect]').forEach(button=>button.onclick=async()=>{try{const word=words.find(w=>w.id===button.dataset.collect),list=await api('/api/collections');const node=dialog('收藏单词',`<form id="collectForm" class="form-stack"><p><b>${esc(word.en)}</b> · ${esc(word.zh)}</p><label>保存到<select name="collectionId"><option value="new">创建新词库</option>${list.map(c=>`<option value="${c.id}">${esc(c.name)}（${c.count} 词）</option>`).join('')}</select></label><label id="newCollectionField">新词库名称<input name="name" value="我的英语单词" maxlength="80"></label><p data-status></p><div class="form-actions"><button type="submit">保存收藏</button></div></form>`);const form=$('#collectForm',node),select=$('[name="collectionId"]',form);if(list.length)select.value=list[0].id;const change=()=>$('#newCollectionField',node).classList.toggle('hidden',select.value!=='new');select.onchange=change;change();bindForm(form,async fd=>{let id=fd.get('collectionId');if(id==='new'){if(!String(fd.get('name')).trim())throw new Error('请填写词库名称');id=(await api('/api/collections',{method:'POST',...json({name:fd.get('name'),track:word.track||'english'})})).id;}await api(`/api/collections/${id}/words`,{method:'POST',...json({wordId:word.id})});node.close();button.textContent='已收藏';toast('已加入个人词库');});}catch(e){toast(e.message,true);}});}
async function collections(){const rows=await api('/api/collections');$('#englishContent').innerHTML=`<section class="card"><div class="card-heading"><div><h2>我的收藏词库</h2><p class="meta">按学习主题收藏单词，然后生成专属练习。</p></div><button class="small" id="newCollection">新建词库</button></div>${rows.length?rows.map(c=>`<div class="bank-row"><span class="bank-symbol">Aa</span><div class="bank-info"><h3>${esc(c.name)}</h3><p class="meta">${c.count} 个单词 · ${esc(trackLabels[c.track]||'英语')}</p></div><div class="actions"><button class="small secondary" data-view-collection="${c.id}">查看单词</button><button class="small" data-practice-collection="${c.id}" ${c.count?'':'disabled'}>开始练习</button></div></div>`).join(''):empty('还没有收藏词库','从本地词典收藏单词，或先创建一个学习主题。','#/english/dictionary','去查词')}</section><div id="collectionWords"></div>`;$('#newCollection').onclick=()=>{const node=dialog('创建个人词库',`<form id="newCollectionForm" class="form-stack"><label>词库名称<input name="name" placeholder="例如：容易混淆的单词" maxlength="80" required></label><label>所属方向<select name="track"><option value="english">英语基础</option><option value="postgraduate" selected>考研英语</option><option value="ielts">雅思</option></select></label><p data-status></p><div class="form-actions"><button type="submit">创建词库</button></div></form>`);bindForm($('#newCollectionForm',node),async fd=>{await api('/api/collections',{method:'POST',...json(Object.fromEntries(fd))});node.close();collections();});};$$('[data-practice-collection]').forEach(button=>button.onclick=()=>{const node=dialog('词库练习',practiceFormHtml('collectionPractice','postgraduate',true));bindPractice($('#collectionPractice',node),button.dataset.practiceCollection);});$$('[data-view-collection]').forEach(button=>button.onclick=async()=>{try{const words=await api(`/api/collections/${button.dataset.viewCollection}/words`);$('#collectionWords').innerHTML=`<div class="section-head"><h2>${esc(rows.find(c=>c.id===button.dataset.viewCollection).name)}</h2></div><div class="word-grid">${words.length?words.map(wordCard).join(''):empty('词库还是空的','在查词结果里点击收藏，将单词加入这个词库。')}</div>`;bindWordActions(words);$('#collectionWords').scrollIntoView({behavior:'smooth'});}catch(e){toast(e.message,true);}});}
async function translation(){const rows=await api('/api/translations');$('#englishContent').innerHTML=`<div class="split-layout"><section class="card"><form id="translationForm" class="form-stack"><label>原文语种<select name="source"><option value="auto">自动识别</option><option value="en">英语</option><option value="zh">中文</option></select></label><label>翻译内容<textarea name="text" rows="7" maxlength="1200" placeholder="输入需要翻译的中文或英文" required></textarea></label><p class="meta" id="translationCount">0 / 1200</p><p data-status aria-live="polite"></p><div class="form-actions"><button type="submit">开始翻译</button></div></form></section><section class="card" id="translationResult">${empty('译文显示在这里','支持中文和英语互译。')}</section></div><section class="card"><div class="card-heading"><h2>最近的翻译</h2></div><div id="translationHistory">${rows.slice(0,12).map((r,i)=>`<div class="bank-row"><div class="bank-info"><h3>${esc(r.text.slice(0,100))}</h3><p class="meta">${date(r.createdAt)}</p></div><button class="small secondary" data-history="${i}">查看</button></div>`).join('')||empty('还没有翻译记录')}</div></section>`;const render=row=>{$('#translationResult').innerHTML=`<div class="card-heading"><h2>翻译结果</h2><span class="badge">${row.provider==='local'?'词库释义':'实时翻译'}</span></div>${Object.entries(row.translations||{}).filter(([k])=>['en','zh'].includes(k)).map(([lang,text])=>`<div><span class="meta">${lang==='en'?'英语':'中文'}</span><p style="white-space:pre-wrap;margin:12px 0 20px" lang="${lang}">${esc(text)}</p><div class="actions"><button class="small secondary" data-copy="${esc(text)}">复制译文</button><button class="small secondary" data-speak="${esc(text)}">朗读</button></div></div>`).join('')}`;$$('[data-copy]').forEach(button=>button.onclick=()=>copyText(button.dataset.copy));$$('[data-speak]').forEach(button=>button.onclick=()=>speak(button.dataset.speak));};const form=$('#translationForm');$('[name="text"]',form).oninput=e=>$('#translationCount').textContent=`${e.target.value.length} / 1200`;bindForm(form,async fd=>{status(form,'正在翻译…');const result=await api('/api/translate',{method:'POST',...json({...Object.fromEntries(fd),track:'english'})});render(result);status(form,'翻译完成');});$$('[data-history]').forEach(button=>button.onclick=()=>render(rows[Number(button.dataset.history)]));}
async function vocabularyImport(){const root=$('#englishContent');root.innerHTML=`<section class="card"><div class="card-heading"><div><h2>补充自己的英语词汇</h2><p class="meta">使用表格批量导入单词、中文释义与例句。</p></div><button class="small secondary" id="wordTemplate">下载表格模板</button></div><form id="vocabImport" class="form-stack"><label>词汇表文件<input name="file" type="file" accept=".xlsx,.csv" required></label><p class="form-note">支持 Excel 或 CSV。先预览，再确认保存。</p><p data-status aria-live="polite"></p><div class="form-actions"><button type="submit">读取并预览</button></div></form></section><div id="vocabPreview"></div>`;$('#wordTemplate').onclick=()=>download('/api/vocabulary/template','英语词汇导入模板.xlsx');bindForm($('#vocabImport'),async fd=>{const preview=await api('/api/vocabulary/preview',{method:'POST',body:fd}),entries=preview.entries||[];$('#vocabPreview').innerHTML=`<section class="card"><h2>词汇预览</h2><p class="meta">可导入 ${entries.length} 条 · 需检查 ${preview.incomplete?.length||0} 条</p>${preview.incomplete?.length?`<div class="notice">以下行未包含完整的单词和释义，请在源表格中修改后重新上传。${preview.incomplete.map(r=>`<p>第 ${esc(r.row??r.line??r.number??'?')} 行：${esc(r.reason||r.error||'内容不完整')}</p>`).join('')}</div>`:''}<div class="table-wrap"><table><thead><tr><th>英语</th><th>中文释义</th><th>方向</th></tr></thead><tbody>${entries.slice(0,40).map(w=>`<tr><td lang="en">${esc(w.en)}</td><td>${esc(w.zh)}</td><td>${esc(trackLabels[w.track]||'英语')}</td></tr>`).join('')}</tbody></table></div>${entries.length>40?'<p class="form-note">仅展示前 40 条，确认时会导入全部有效词条。</p>':''}<p id="wordImportStatus" class="error" aria-live="polite"></p><div class="form-actions"><button id="confirmWords" ${entries.length?'':'disabled'}>导入 ${entries.length} 条有效词汇</button></div></section>`;$('#confirmWords').onclick=async event=>{event.currentTarget.disabled=true;try{const result=await api('/api/vocabulary/import',{method:'POST',...json({entries})});toast(`导入完成：新增 ${result.added} 条，跳过重复 ${result.duplicates} 条`);go('#/english/dictionary');}catch(e){$('#wordImportStatus').textContent=e.message;$('#confirmWords').disabled=false;}};});}

const ieltsInfo={reading:{name:'阅读',english:'READING',description:'阅读材料与标准答案练习'},listening:{name:'听力',english:'LISTENING',description:'配合自己的音频与听力试题'},writing:{name:'写作',english:'WRITING',description:'记录文章，整理修改与复盘'},speaking:{name:'口语',english:'SPEAKING',description:'整理话题、表达与练习笔记'}};
async function ielts(selected='reading'){if(!ieltsInfo[selected])selected='reading';const allBanks=await api('/api/banks'),rows=allBanks.filter(b=>b.track==='ielts'&&b.module===selected);app.innerHTML=heading('雅思学习','','<button class="secondary" id="ieltsWords">练习雅思词汇</button>')+`<div id="ieltsContent"></div>`;$('#ieltsWords').onclick=()=>{const node=dialog('雅思词汇练习',practiceFormHtml('ieltsWordPractice','ielts'));bindPractice($('#ieltsWordPractice',node));};if(['writing','speaking'].includes(selected))return journal(selected);$('#ieltsContent').innerHTML=`${selected==='listening'?'<div class="read-only-banner">播放你已有的听力音频，并在导入的配套试题中作答。当前资料导入支持文字题目与答案。</div>':''}<div class="section-head"><h2>${ieltsInfo[selected].name}专项题库</h2><a class="button small" href="/import/ielts/${selected}">导入${ieltsInfo[selected].name}题库</a></div><section class="grid">${rows.length?rows.map(bankCard).join(''):`<div class="card">${empty(`添加${ieltsInfo[selected].name}练习资料`,'导入带答案的题目。组卷后将按你提供的标准答案判分。',`#/import/ielts/${selected}`,'导入资料')}</div>`}</section>`;}
async function journal(module){const speaking=module==='speaking',rows=(await api(`/api/study/journal?track=ielts&module=${module}`)).filter(x=>x.track==='ielts'&&x.module===module),root=$('#ieltsContent');root.innerHTML=`<div class="split-layout"><section class="card"><div class="card-heading"><div><h2>${speaking?'记录一次口语练习':'开始一篇写作练习'}</h2><p class="meta">${speaking?'保存话题、表达和复盘笔记。':'保存文章与修改要点，对照自己的资料复盘。'}</p></div></div><form id="journalForm" class="form-stack"><label>${speaking?'话题或问题':'写作题目'}<textarea name="prompt" rows="3" placeholder="${speaking?'例如：Describe a place you enjoyed visiting.':'输入 Task 1 / Task 2 写作题目'}" required maxlength="10000"></textarea></label><label>${speaking?'我的表达或练习提纲':'我的文章'}<textarea name="response" rows="10" placeholder="${speaking?'记录想说的内容、关键词或练习后的转写…':'在这里写下你的文章…'}" required maxlength="30000"></textarea></label><p id="journalCounter" class="journal-counter">0 个英文词</p><details class="self-check"><summary>自查清单</summary><p class="meta">${speaking?'检查：是否回应问题、表达是否连贯、用词是否准确；结合自己的录音检查发音。':'检查：是否回应全部要求、段落是否清楚、论据是否充分、词汇和语法是否准确。'}</p></details><label>自查与改进笔记<textarea name="notes" rows="3" placeholder="${speaking?'例如：句子衔接、发音难点、下次想改进的表达':'例如：是否回应题目、段落逻辑、词汇与语法修改'}" maxlength="10000"></textarea></label><p class="form-note">这是练习与自查记录，不生成雅思评分。</p><p data-status aria-live="polite"></p><div class="form-actions"><button type="submit">保存练习记录</button></div></form></section><section class="card"><div class="card-heading"><h2>之前的练习</h2><span class="badge">${rows.length} 条</span></div>${rows.length?rows.map((r,i)=>`<article class="journal-item"><h3>${esc(r.prompt)}</h3><p class="meta">${date(r.createdAt)}</p><div class="journal-response">${esc(r.response)}</div>${r.notes?`<details style="margin-top:10px"><summary>我的复盘笔记</summary><p class="journal-response">${esc(r.notes)}</p></details>`:''}<div class="actions"><button class="small secondary" data-journal-copy="${i}">复制内容</button><button class="small ghost" data-journal-delete="${r.id}">删除</button></div></article>`).join(''):'<p class="meta">还没有保存的练习。</p>'}</section></div>`;const form=$('#journalForm'),key=`quizforge-journal-${accountName()}-${module}`;try{const draft=JSON.parse(localStorage.getItem(key)||'null');if(draft)for(const [name,value] of Object.entries(draft)){const field=$(`[name="${name}"]`,form);if(field)field.value=value;}}catch{}const update=()=>{const value=$('[name="response"]',form).value;$('#journalCounter').textContent=`${(value.match(/[A-Za-z]+(?:['’-][A-Za-z]+)*/g)||[]).length} 个英文词`;localStorage.setItem(key,JSON.stringify(Object.fromEntries(new FormData(form))));};form.oninput=update;update();bindForm(form,async fd=>{await api('/api/study/journal',{method:'POST',...json({track:'ielts',module,...Object.fromEntries(fd)})});localStorage.removeItem(key);toast('练习记录已保存');journal(module);});$$('[data-journal-copy]').forEach(button=>button.onclick=()=>{const row=rows[Number(button.dataset.journalCopy)];copyText(`${row.prompt}\n\n${row.response}\n\n${row.notes||''}`);});$$('[data-journal-delete]').forEach(button=>button.onclick=async()=>{if(!confirm('删除这条练习记录？'))return;try{await api(`/api/study/journal/${button.dataset.journalDelete}`,{method:'DELETE'});journal(module);}catch(e){toast(e.message,true);}});}

async function settings(){app.innerHTML=heading('账号设置','所有账号都可以管理题库、学习和查看自己的记录。')+`<div class="settings-grid"><section class="card"><div class="card-heading"><div><h2>${esc(accountName())}</h2><p class="meta">当前登录账号</p></div><span class="badge green">已登录</span></div><form id="passwordForm" class="form-stack"><label>当前密码<input type="password" name="currentPassword" autocomplete="current-password" required></label><label>新密码<input type="password" name="newPassword" autocomplete="new-password" minlength="6" required></label><label>再次输入新密码<input type="password" name="confirmPassword" autocomplete="new-password" minlength="6" required></label><p class="form-note">新密码至少 6 位，不要求混合大小写或符号。</p><p data-status aria-live="polite"></p><div class="form-actions"><button type="submit">修改密码</button></div></form></section></div>`;bindForm($('#passwordForm'),async fd=>{if(fd.get('newPassword')!==fd.get('confirmPassword'))throw new Error('两次输入的新密码不一致。');await api('/api/account/password',{method:'POST',...json({currentPassword:fd.get('currentPassword'),newPassword:fd.get('newPassword')})});toast('密码已更新，请重新登录。');sessionStorage.removeItem('quizforge-session-token');go('#/login');});}
async function copyText(text){try{if(navigator.clipboard?.writeText){await navigator.clipboard.writeText(text);toast('已复制');return;}const node=dialog('复制内容','<p class="form-note">已选中内容，请按 Ctrl+C 或长按复制。</p><textarea id="copyArea" rows="8"></textarea>');$('#copyArea',node).value=text;$('#copyArea',node).select();}catch{toast('无法复制，请手动选择文本。',true);}}
async function download(url,filename){try{const response=await fetch(url,{headers:{'x-session-token':token()}});if(!response.ok){const data=await response.json().catch(()=>({}));throw new Error(data.error||'导出失败');}const href=URL.createObjectURL(await response.blob()),link=document.createElement('a');link.href=href;link.download=filename;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(href),10000);}catch(error){toast(error.message,true);}}
async function route(){cleanup();cleanup=()=>{};$$('dialog').forEach(node=>node.close());const parts=location.pathname.replace(/^\//,'').split('/'),page=parts[0];document.body.classList.toggle('exam-focus',page==='exam'&&Boolean(token()));if(!token()||page==='login')return login();let section=['bank','banks','import','build','exam','attempt','results','wrong'].includes(page)?'banks':page==='english'?'english':page==='ielts'?'ielts':page==='corpus'?'corpus':page==='flights'?'flights':'home';setNavigation(section);app.innerHTML='<div class="loading" role="status">正在加载…</div>';window.scrollTo(0,0);try{if(['banks','english','ielts'].includes(page)&&['results','wrong'].includes(parts[1])){const scope=page==='english'?(new URLSearchParams(location.search).get('track')==='english'?'english':'postgraduate'):page==='ielts'?'ielts':'general';if(parts[1]==='results')await results(scope);else await wrong(scope);}else if(page==='banks'||page==='materials')await banks();else if(page==='bank'||page==='edit-questions')await bankDetail(parts[1]);else if(page==='import')await importPage(parts[1]||'general',parts[2]||'general');else if(page==='build')await build(parts[1]);else if(page==='exam')await exam(parts[1]);else if(page==='attempt'){const track=await attempt(parts[1]);section=scopeRoot(track);}else if(page==='results')return go('/banks/results');else if(page==='wrong')return go('/banks/wrong');else if(page==='english')await english(parts[1]||'overview');else if(page==='ielts')await ielts(parts[1]||'reading');else if(page==='dictionary')return go('/english/dictionary');else if(page==='library')return go('/english/collections');else if(page==='translate')return go('/english/translate');else if(page==='corpus')await showCorpus({app,api,esc,heading,dialog,bindForm,json,toast},parts[1]);else if(page==='flights')cleanup=await showFlights({app,api,esc,heading,json,toast,dialog});else if(page==='settings')return go('/');else await home();let active=location.pathname;if(active==='/english/overview')active='/english';if(active==='/ielts')active='/ielts/reading';if(page!=='exam')app.insertAdjacentHTML('afterbegin',moduleNavigation(section,active));}catch(error){if(token())app.innerHTML=heading('暂时无法打开此页面')+`<section class="card"><p class="error">${esc(error.message)}</p><div class="form-actions"><a class="button secondary" href="/">返回首页</a><button id="retryPage">重试</button></div></section>`;$('#retryPage')?.addEventListener('click',route);}}
window.addEventListener('popstate',route);
window.addEventListener('hashchange',()=>{history.replaceState(null,'',location.hash.slice(1)||'/');route();});
document.addEventListener('click',event=>{const link=event.target.closest('a[href]');if(!link||event.button!==0||event.ctrlKey||event.metaKey||event.shiftKey||event.altKey||link.target||link.download)return;const url=new URL(link.href,location.href);if(url.origin!==location.origin)return;const target=url.hash.startsWith('#/')?url.hash.slice(1):url.pathname+url.search;if(!url.hash.startsWith('#/')&&!/^\/(?:$|login$|banks(?:\/|$)|bank\/|import(?:\/|$)|build\/|exam\/|attempt\/|results$|wrong$|english(?:\/|$)|ielts(?:\/|$)|corpus(?:\/|$)|flights$|settings$)/.test(target))return;event.preventDefault();go(target);});
if(location.hash)history.replaceState(null,'',location.hash.replace(/^#/, '')||'/');
window.addEventListener('beforeunload',()=>cleanup());
route();
